components.css:
:root { color-scheme: light dark; font: 13px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: var(--wm-text, #242428); background: var(--wm-content, #fafafa); }
* { box-sizing: border-box; }
body { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; min-height: 32px; padding: 5px 10px; background: transparent; border: 0; border-radius: 6px; white-space: nowrap; }
button:hover { background: var(--wm-fill-strong, #8882); }
button:disabled { opacity: .45; cursor: default; }
button.primary { background: var(--wm-primary, #242428); color: var(--wm-primary-text, #fafafa); }
:focus-visible { outline: 2px solid var(--wm-text, #555); outline-offset: -2px; }
input { background: var(--wm-content, #fff); border: 1px solid var(--wm-hairline, #8885); border-radius: 6px; padding: 9px; width: 100%; }
main { height: 100vh; height: 100dvh; display: flex; flex-direction: column; overflow: hidden; }
#workspace { min-height: 0; flex: 1; display: grid; grid-template-columns: minmax(240px, 39%) minmax(0, 1fr); }
#workspace.preview-only { grid-template-columns: minmax(0, 1fr); }
#workspace.preview-only #source-pane { display: none; }
section { min-width: 0; min-height: 0; }
#source-pane { display: flex; flex-direction: column; border-right: 1px solid var(--wm-hairline, #8883); }
.pane-heading { display: flex; align-items: center; min-height: 36px; flex: none; padding: 0 12px; gap: 8px; }
.pane-heading label { font-weight: 600; }
#position { margin-left: auto; font-variant-numeric: tabular-nums; color: var(--wm-text-dim, #73737b); }
textarea { flex: 1; width: 100%; min-height: 0; resize: none; border: 0; border-radius: 0; outline: none; padding: 8px 12px 16px; font: 13px/1.65 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; tab-size: 2; white-space: pre; color: inherit; caret-color: currentColor; background: var(--wm-content, #fafafa); }
textarea:focus-visible { outline: 1px solid var(--wm-hairline, #8886); }
::selection { background: var(--wm-fill-strong, #8885); }
#preview-pane { position: relative; display: flex; flex-direction: column; }
#preview-tools { display: flex; align-items: center; gap: 2px; min-height: 36px; padding: 0 8px; flex-wrap: wrap; }
#preview-tools .space { flex: 1; }
select { border: 0; background: transparent; padding: 5px; }
#actual { min-width: 48px; font-variant-numeric: tabular-nums; }
button svg { width: 16px; height: 16px; display: block; pointer-events: none; }
.icon { width: 32px; padding: 8px; display: inline-flex; align-items: center; justify-content: center; }
#drawing-area { min-height: 0; flex: 1; display: flex; }
#tools { width: 44px; flex: none; display: flex; flex-direction: column; align-items: center; padding: 8px 6px; gap: 4px; background: var(--wm-content, #fafafa); }
#tools button[aria-pressed="true"] { background: var(--wm-fill-strong, #8882); font-weight: 600; }
.tool-space { flex: 1; }
#selection-tools { position: absolute; z-index: 2; top: 8px; left: 52px; display: flex; align-items: center; gap: 2px; padding: 2px; border-radius: 6px; background: var(--wm-surface, #fafafa); box-shadow: 0 1px 4px #0002; }
#surface { position: relative; flex: none; }
#overlay { position: absolute; inset: 0; width: 100%; height: 100%; touch-action: none; }
#object-list { display: flex; flex-direction: column; max-height: 50vh; overflow: auto; }
#object-list button { text-align: left; }
#viewport { flex: 1; min-height: 0; overflow: auto; background: var(--wm-fill, #8881); cursor: grab; touch-action: pan-x pan-y; }
#viewport.panning { cursor: grabbing; user-select: none; }
#canvas { display: flex; align-items: center; justify-content: center; width: max-content; height: max-content; min-width: 100%; min-height: 100%; padding: 24px; }
#image { display: block; flex: none; max-width: none; background: white; user-select: none; pointer-events: none; }
#image.paper-dark { background: #18181b; }
#image.paper-none { background: transparent; }
#preview-empty { padding: 20px; color: var(--wm-text-dim, #73737b); }
wm-notice { flex: none; }
[hidden] { display: none !important; }
dialog { width: min(500px, calc(100vw - 24px)); padding: 24px; color: var(--wm-text, #242428); background: var(--wm-surface, var(--wm-content, #fafafa)); border: 1px solid var(--wm-hairline, #8884); border-radius: 12px; }
dialog::backdrop { background: #0005; }
dialog h2 { font-size: 20px; margin: 0 0 12px; }
dialog p { line-height: 1.6; margin: 0 0 16px; }
dialog label { display: block; margin: 12px 0 6px; }
.actions { display: flex; gap: 6px; justify-content: flex-end; margin-top: 16px; }
#draft-list { display: flex; flex-direction: column; max-height: 50vh; overflow: auto; gap: 4px; }
#draft-list button { text-align: left; white-space: normal; overflow-wrap: anywhere; }
@media (max-width: 650px) {
  #workspace { grid-template-columns: minmax(0, 1fr); grid-template-rows: 42% minmax(0, 1fr); }
  #source-pane { border-right: 0; border-bottom: 1px solid var(--wm-hairline, #8883); }
  #workspace.preview-only { grid-template-rows: minmax(0, 1fr); }
  #preview-tools { padding: 0 4px; }
}

